c='p8';B='AI 3'
def PR(tag,title,code,desc,note='',fs=19,ofs=22):
    o=RUN(code)
    return S2(c,B+' · '+tag,title,card('Ý chính',desc)+CODE(code,fs),RES(OUT(o,ofs),'Kết quả chạy Python thật')+(KEY(note) if note else ''))
S=[]
S.append(TITLE('TIN HỌC · AI 3','ĐÁNH GIÁ MÔ HÌNH,<br>QUÁ KHỚP','Chia dữ liệu huấn luyện – kiểm định – kiểm tra, quá khớp và chưa khớp, rò rỉ dữ liệu, ma trận nhầm lẫn, accuracy, precision, recall, F1 và bẫy dữ liệu mất cân bằng.',['train/test','quá khớp','rò rỉ','precision','recall']))
S.append(goals(c,B,['Giải thích vì sao <b>chia dữ liệu</b> thành 3 tập.','Nhận ra <b>quá khớp</b> và <b>chưa khớp</b> qua số liệu.','Nhận diện <b>rò rỉ dữ liệu</b>.','Đọc <b>ma trận nhầm lẫn</b>; tính <b>accuracy, precision, recall, F1</b>.','Hiểu bẫy <b>accuracy cao trên dữ liệu mất cân bằng</b>.'],['Chia dữ liệu','Quá khớp','Rò rỉ dữ liệu','Ma trận nhầm lẫn','Bẫy mất cân bằng']))
S.append(S2(c,B+' · 1','Vì sao phải chia dữ liệu?',card('Ba tập với ba vai trò',T(tr('Tập','Dùng để',h=True)+tr('<b>Huấn luyện</b>','mô hình <b>học</b>')+tr('<b>Kiểm định</b>','<b>chỉnh tham số</b> (ví dụ chọn k)')+tr('<b>Kiểm tra</b>','đánh giá cuối, <b>dữ liệu chưa thấy</b>'))),KEY('Mục đích: đo <b>khả năng tổng quát hoá</b> trên dữ liệu chưa thấy.')))
S.append(S2(c,B+' · 2','Quá khớp và chưa khớp',card('Đọc qua điểm số',T(tr('Huấn luyện','Kiểm tra','Kết luận',h=True)+tr('99%','62–70%','<b>quá khớp</b> (học thuộc)')+tr('thấp','thấp','<b>chưa khớp</b> (mô hình quá đơn giản)')+tr('cao','cao','tốt')),P('Hướng khắc phục quá khớp: <b>thêm dữ liệu</b>, <b>đơn giản hoá mô hình</b>, <b>kiểm định chéo</b>.')),KEY('Chênh lệch lớn giữa huấn luyện và kiểm tra là <b>dấu hiệu quá khớp</b>.')))
S.append(S2(c,B+' · 3','Rò rỉ dữ liệu',card('Thông tin kiểm tra lọt vào huấn luyện',P('<b>Chuẩn hoá cả tập</b> (trung bình, độ lệch chuẩn tính trên cả huấn luyện lẫn kiểm tra) rồi mới chia → <b>rò rỉ</b>: kết quả <b>lạc quan</b>.','Dùng <b>tập kiểm tra để chỉnh tham số</b> → đánh giá không khách quan.','Cách đúng: <b>chia trước</b>; tham số chuẩn hoá tính <b>chỉ trên tập huấn luyện</b>, rồi áp sang tập kiểm tra.')),KEY('Quy tắc: <b>chia tập trước, xử lí sau</b>.')))
S.append(S2(c,B+' · 4','Ma trận nhầm lẫn',card('Bốn ô',T(tr('','Dự đoán dương','Dự đoán âm',h=True)+tr('Thật dương','<b>TP</b>','<b>FN</b> (bỏ sót)')+tr('Thật âm','<b>FP</b> (báo nhầm)','<b>TN</b>')),P('<b>Dương</b> là lớp ta quan tâm (thư rác, bệnh).')),KEY('FN: dương thật bị <b>bỏ sót</b>; FP: âm thật bị <b>báo nhầm</b>.')))
S.append(S2(c,B+' · 4','Bốn chỉ số',card('Công thức',T(tr('Chỉ số','Công thức','Ý nghĩa',h=True)+tr('Accuracy','(TP+TN)/tổng','tỉ lệ đoán đúng')+tr('Precision','TP/(TP+FP)','trong số <b>báo dương</b>, bao nhiêu đúng')+tr('Recall','TP/(TP+FN)','trong số <b>dương thật</b>, bắt được bao nhiêu')+tr('F1','2PR/(P+R)','trung bình điều hoà'))),KEY('Recall = độ nhạy; <b>tỉ lệ âm tính giả = 1 − recall</b>.')))
S.append(PR('4','Bài mẫu: TP=40, FP=10, FN=20, TN=30',"TP,FP,FN,TN=40,10,20,30\nn=TP+FP+FN+TN\nP=TP/(TP+FP); R=TP/(TP+FN)\nprint('accuracy',(TP+TN)/n)\nprint('precision',P)\nprint('recall',round(R,3))\nprint('F1',round(2*P*R/(P+R),3))\nprint('bỏ sót',FN)",P('Accuracy = 70/100 = <b>70%</b>; precision = 40/50 = <b>80%</b>.','Recall = 40/60 ≈ <b>66,7%</b> (không phải 80%).','<b>20</b> thư rác bị bỏ sót (FN).'),'Đừng nhầm precision với recall.',17,22))
S.append(PR('4','Bài mẫu: 40 thư rác, báo 30, đúng 24',"TP=24; FP=30-24; FN=40-24; TN=100-TP-FP-FN\nprint('P',TP/30,'R',TP/40)\nprint('FN',FN,'TN',TN)\nprint('accuracy',(TP+TN)/100)",P('Precision = 24/30 = <b>0,8</b>; recall = 24/40 = <b>0,6</b>.','FN = 40 − 24 = <b>16</b>; TN = 54; accuracy = <b>0,78</b>.'),'Accuracy không bằng precision.',20,24))
S.append(PR('5','Bẫy: 95% âm tính, mô hình luôn đoán “âm”',"n=100; pos=5\nTP=0; FN=pos; TN=n-pos; FP=0\nprint('accuracy',(TP+TN)/n)\nprint('recall',TP/(TP+FN))\nprint('precision','không xác định (không báo dương nào)')",P('Accuracy = <b>95%</b> nhưng <b>recall = 0</b>: bỏ sót mọi ca dương.','Dữ liệu <b>mất cân bằng</b> → cần xét <b>precision, recall, F1</b>.'),'Đáp án: accuracy 95% nhưng recall lớp dương = 0.',19,24))
S.append(S2(c,B+' · 5','Chọn chỉ số theo bài toán',card('Cái giá của sai lầm',T(tr('Bài toán','Ưu tiên',h=True)+tr('Chẩn đoán bệnh hiểm','<b>recall</b> cao (đừng bỏ sót)')+tr('Lọc thư rác (không mất thư quan trọng)','<b>precision</b> cao')+tr('Cân bằng hai mặt','<b>F1</b>'))),KEY('Chọn chỉ số theo <b>hậu quả</b> của FN và FP.')))
S.append(SELF(c,B+' · 6','Tự kiểm tra 1: quá khớp','Mô hình 98% trên huấn luyện, 70% trên kiểm tra. Nguyên nhân thường gặp?','',P('<b>Quá khớp</b>: học thuộc dữ liệu huấn luyện, khó tổng quát hoá.'),22))
S.append(SELF(c,B+' · 6','Tự kiểm tra 2: tính chỉ số','TP=24, FP=6, FN=16, TN=54. Tính precision, recall, accuracy.','',P('Precision = 24/30 = <b>0,8</b>; recall = 24/40 = <b>0,6</b>; accuracy = 78/100 = <b>0,78</b>.'),22))
S.append(SELF(c,B+' · 6','Tự kiểm tra (HSG): đúng hay sai?','(a) Chuẩn hoá cả tập rồi chia là cách đúng. (b) Dùng tập kiểm tra chỉnh tham số giúp đánh giá khách quan. (c) Accuracy 95% luôn là mô hình tốt. (d) Recall = TP/(TP+FN). (e) 99% huấn luyện, 70% kiểm tra là dấu hiệu quá khớp.','',P('(a) <b>Sai</b>: rò rỉ.','(b) <b>Sai</b>: rò rỉ.','(c) <b>Sai</b>: xét mất cân bằng.','(d) <b>Đúng</b>.','(e) <b>Đúng</b>.'),20))
